<script setup lang="ts">import{site}from'~/data/site';const route=useRoute();const form=reactive({name:'',email:'',subject:typeof route.query.departement==='string'?'À propos du département : '+route.query.departement:'',message:''});const error=ref('');const prepared=ref(false);function submit(){error.value='';if(!form.name.trim()||!form.email.trim()||!form.message.trim()){error.value='Merci de renseigner votre nom, votre adresse e-mail et votre message.';return}if(!site.email){error.value='L’adresse e-mail officielle doit être configurée par l’administration.';return}const body=encodeURIComponent('Nom : '+form.name+'\nE-mail : '+form.email+'\nSujet : '+form.subject+'\n\n'+form.message);window.location.href='mailto:'+site.email+'?subject='+encodeURIComponent(form.subject||'Message depuis le site MIREF')+'&body='+body;prepared.value=true}useSeoMeta({title:'Contact & visite',description:'Contactez MIREF, posez vos questions ou préparez votre première visite.'})</script>
<template><div><section class="page-hero purple-gradient"><div class="container-wide"><span class="eyebrow">Nous sommes à votre écoute</span><h1>Un premier message.<br><em>Une belle rencontre.</em></h1><p>Une question, une demande de prière ou l’envie de nous rendre visite ? Écrivez-nous, nous serons heureux de vous lire.</p></div></section><section class="section-space"><div class="container-wide grid"><div class="copy"><span class="eyebrow">Entrons en contact</span><h2 class="section-title">Nous serions heureux de faire votre connaissance.</h2><p>Que vous souhaitiez découvrir l’église, en savoir plus sur nos activités ou échanger avec notre équipe, ce formulaire est un premier pas.</p><div class="detail"><i class="pi pi-phone"/><span><small>Téléphone</small><b>{{site.phone}}</b></span></div><div class="detail"><i class="pi pi-envelope"/><span><small>E-mail</small><b>{{site.email||'Adresse e-mail à confirmer'}}</b></span></div><div class="detail"><i class="pi pi-map-marker"/><span><small>Localisation</small><b>{{site.address||'Adresse à confirmer'}}</b><small>{{site.location}}</small></span></div><a :href="site.facebook" target="_blank" rel="noopener" class="facebook"><i class="pi pi-facebook"/>Retrouvons-nous sur Facebook <i class="pi pi-arrow-up-right"/></a></div><form class="form" @submit.prevent="submit"><span class="eyebrow">Votre message</span><h3>Comment pouvons-nous vous aider ?</h3><label>Nom complet<input v-model="form.name" class="form-field" autocomplete="name" placeholder="Votre nom" required></label><label>Adresse e-mail<input v-model="form.email" class="form-field" type="email" autocomplete="email" placeholder="vous@exemple.com" required></label><label>Sujet<input v-model="form.subject" class="form-field" placeholder="Le sujet de votre message"></label><label>Votre message<textarea v-model="form.message" class="form-field" rows="5" placeholder="Écrivez votre message ici…" required/></label><p v-if="error" class="error" role="alert">{{error}}</p><p v-